/**
 * The automation sub-type tables (Phase 1). An automation is a COMPOSITE: one
 * `elementum_automation` + one `elementum_workflow_publish` + one trigger block
 * + N task blocks, each trigger/task kind its own terraform resource type. This
 * is the automation analogue of `entities/agent-tool/types.ts`: per-sub-type
 * knowledge is one ROW, and only *implemented* kinds round-trip.
 *
 * Phase 1 implements the `onDemand` trigger and the `executeScript` +
 * `setVariable` (create form) tasks end to end. Every other kind is DECLARED so
 * the pull partition REPORTS it by name (plan §6) instead of "unknown resource",
 * and adoption/build-vs-export scope ONLY the implemented resource types — an adopted
 * kind the printer can't reconstruct would plan as a destroy on rebuild.
 *
 * `typeKey` is the wire discriminant the authoring builders emit
 * (`triggers.ts` trigger `wire` keys, `tasks.ts` `ActionDef.key`); `resourceType`
 * is the terraform type ei's export uses. Only the implemented rows' `typeKey`
 * is load-bearing (to-tf maps authored → resource by it); the declared rows
 * need only an accurate `resourceType` for from-tf recognition.
 */
/** The automation's own resource + its versioning/publish resource. */
export const AUTOMATION_RESOURCE_TYPE = "elementum_automation";
export const WORKFLOW_PUBLISH_RESOURCE_TYPE = "elementum_workflow_publish";
export const TABLE_RECORDS_SEARCH_TASK_RESOURCE_TYPE = "elementum_table_records_search_task";
/** Trigger kinds. One trigger per automation. Phase 1: onDemand only. */
export const TRIGGER_SUB_TYPES = [
    { typeKey: "onDemand", resourceType: "elementum_on_demand_trigger", implemented: true },
    { typeKey: "createRecord", resourceType: "elementum_record_created_trigger", implemented: true },
    { typeKey: "updateRecord", resourceType: "elementum_record_updated_trigger", implemented: true },
    { typeKey: "webhook", resourceType: "elementum_webhook_trigger", implemented: true },
    { typeKey: "approvalChain", resourceType: "elementum_approval_chain_trigger", implemented: true },
    { typeKey: "attachment", resourceType: "elementum_attachment_added_trigger", implemented: true },
    { typeKey: "datamine", resourceType: "elementum_datamine_trigger", implemented: true },
    { typeKey: "emailReceived", resourceType: "elementum_email_ingestion_trigger", implemented: true },
    { typeKey: "commentAdded", resourceType: "elementum_comment_added_trigger", implemented: true },
    { typeKey: "conversationEnd", resourceType: "elementum_agent_conversation_ended_trigger", implemented: true },
    { typeKey: "slackMessage", resourceType: "elementum_slack_message_trigger", implemented: true },
    { typeKey: "survey", resourceType: "elementum_survey_trigger", implemented: true },
    { typeKey: "schedule", resourceType: "elementum_schedule_trigger", implemented: true },
];
/**
 * Task kinds. All rows are implemented as of `aiFileAnalysis` (the last
 * holdout — it needs its `elementum_ai_file_reader` target to also round-trip,
 * see `entities/file-reader/types.ts`). `variable` (setVariable's create
 * form) is the one worth calling out: the tf dialect carries ONE variable per
 * task as variable_name/variable_type/value, and the provider's variable_id
 * is COMPUTED, so the compose-path client UUID never reaches HCL. A future
 * new task kind lands here declared-only first (see the doc comment on
 * {@link ALL_AUTOMATION_TASK_TYPE_SET} below) until its row flips implemented.
 */
export const TASK_SUB_TYPES = [
    { typeKey: "executeScript", resourceType: "elementum_execute_script_task", implemented: true },
    { typeKey: "variable", resourceType: "elementum_variable_task", implemented: true },
    { typeKey: "updateVariable", resourceType: "elementum_update_variable_task", implemented: true },
    { typeKey: "updateField", resourceType: "elementum_update_field_task", implemented: true },
    { typeKey: "recordSearch", resourceType: "elementum_record_search_task", implemented: true },
    { typeKey: "tableRecordsSearch", resourceType: TABLE_RECORDS_SEARCH_TASK_RESOURCE_TYPE, implemented: true },
    { typeKey: "createRecord", resourceType: "elementum_create_record_task", implemented: true },
    { typeKey: "findRelatedRecords", resourceType: "elementum_find_related_records_task", implemented: true },
    { typeKey: "relateRecords", resourceType: "elementum_relate_records_task", implemented: true },
    { typeKey: "sendEmail", resourceType: "elementum_send_email_task", implemented: true },
    { typeKey: "message", resourceType: "elementum_message_task", implemented: true },
    { typeKey: "notification", resourceType: "elementum_notification_task", implemented: true },
    { typeKey: "aiAgent", resourceType: "elementum_ai_agent_task", implemented: true },
    { typeKey: "aiClassify", resourceType: "elementum_ai_classify_task", implemented: true },
    { typeKey: "aiSummarize", resourceType: "elementum_ai_summarize_task", implemented: true },
    { typeKey: "aiTransform", resourceType: "elementum_ai_transform_task", implemented: true },
    { typeKey: "aiSearchTable", resourceType: "elementum_ai_search_table_task", implemented: true },
    { typeKey: "aiFileAnalysis", resourceType: "elementum_ai_file_read_task", implemented: true },
    { typeKey: "api", resourceType: "elementum_api_task", implemented: true },
    { typeKey: "calculation", resourceType: "elementum_calculation_task", implemented: true },
    { typeKey: "procedure", resourceType: "elementum_procedure_task", implemented: true },
    { typeKey: "runAutomation", resourceType: "elementum_run_automation_task", implemented: true },
    { typeKey: "documentModel", resourceType: "elementum_file_reader_task", implemented: true },
    { typeKey: "approvalChain", resourceType: "elementum_approval_chain_task", implemented: true },
    { typeKey: "approvalStatusUpdate", resourceType: "elementum_approval_status_update_task", implemented: true },
    { typeKey: "addWatcher", resourceType: "elementum_add_watcher_task", implemented: true },
    { typeKey: "saveAttachment", resourceType: "elementum_save_attachment_task", implemented: true },
    { typeKey: "userSearch", resourceType: "elementum_user_search_task", implemented: true },
    { typeKey: "aspectRecordFieldLocking", resourceType: "elementum_aspect_record_field_locking_task", implemented: true },
    { typeKey: "initiateCall", resourceType: "elementum_initiate_call_task", implemented: true },
    // Operators (branching) — later phases:
    { typeKey: "forEach", resourceType: "elementum_for_each_task", implemented: true },
    { typeKey: "forkJoin", resourceType: "elementum_fork_join_task", implemented: true },
    { typeKey: "switch", resourceType: "elementum_switch_task", implemented: true },
];
export const BRANCH_SUB_TYPES = [
    { typeKey: "switchCase", resourceType: "elementum_switch_case", implemented: true },
    { typeKey: "forkJoinBranch", resourceType: "elementum_fork_join_branch", implemented: true },
];
export const ALL_AUTOMATION_SUB_TYPES = [...TRIGGER_SUB_TYPES, ...TASK_SUB_TYPES, ...BRANCH_SUB_TYPES];
export const AUTOMATION_SUB_TYPE_BY_TYPE_KEY = new Map(ALL_AUTOMATION_SUB_TYPES.map((t) => [t.typeKey, t]));
export const AUTOMATION_SUB_TYPE_BY_RESOURCE = new Map(ALL_AUTOMATION_SUB_TYPES.map((t) => [t.resourceType, t]));
/** Trigger/task resource types the terraform path round-trips today. */
export const IMPLEMENTED_TRIGGER_RESOURCE_TYPES = TRIGGER_SUB_TYPES.filter((t) => t.implemented === true).map((t) => t.resourceType);
export const IMPLEMENTED_TASK_RESOURCE_TYPES = TASK_SUB_TYPES.filter((t) => t.implemented === true).map((t) => t.resourceType);
/**
 * The resource types adoption/build-vs-export scope for automations: the automation +
 * workflow_publish skeleton plus the implemented trigger/task kinds. Composite,
 * so the whole set moves together.
 */
export const IMPLEMENTED_AUTOMATION_RESOURCE_TYPES = [
    AUTOMATION_RESOURCE_TYPE,
    WORKFLOW_PUBLISH_RESOURCE_TYPE,
    ...IMPLEMENTED_TRIGGER_RESOURCE_TYPES,
    ...IMPLEMENTED_TASK_RESOURCE_TYPES,
    ...BRANCH_SUB_TYPES.map((t) => t.resourceType),
];
/** Every declared automation-family resource type — the partition recognizes these by name. */
export const ALL_AUTOMATION_RESOURCE_TYPES = [
    AUTOMATION_RESOURCE_TYPE,
    WORKFLOW_PUBLISH_RESOURCE_TYPE,
    ...ALL_AUTOMATION_SUB_TYPES.map((t) => t.resourceType),
];
export const AUTOMATION_RESOURCE_TYPES = IMPLEMENTED_AUTOMATION_RESOURCE_TYPES;
export const AUTOMATION_TRIGGER_TYPES = IMPLEMENTED_TRIGGER_RESOURCE_TYPES;
export const AUTOMATION_TASK_TYPES = IMPLEMENTED_TASK_RESOURCE_TYPES;
export const AUTOMATION_BRANCH_TYPES = BRANCH_SUB_TYPES.map((t) => t.resourceType);
export const AUTOMATION_TRIGGER_TYPE_SET = new Set(AUTOMATION_TRIGGER_TYPES);
export const AUTOMATION_TASK_TYPE_SET = new Set(AUTOMATION_TASK_TYPES);
/**
 * Every DECLARED task resource type, implemented or not — for from-tf's graph
 * walk (which task blocks belong to this automation's tree) and its
 * dependency-recognition checks. Deliberately broader than
 * {@link AUTOMATION_TASK_TYPE_SET} (implemented-only, the adoption/build-vs-export
 * scope): a declared-but-unimplemented type (none currently declared — a
 * future new task kind lands here first, before its row flips implemented)
 * must still be walked into the task graph so from-tf's own dedicated
 * diagnostic for it fires, rather than the block silently falling out of the
 * graph and surfacing as an unrelated "unresolved parent"/"orphaned task"
 * error.
 */
export const ALL_AUTOMATION_TASK_TYPE_SET = new Set(TASK_SUB_TYPES.map((t) => t.resourceType));
export const AUTOMATION_BRANCH_TYPE_SET = new Set(AUTOMATION_BRANCH_TYPES);
